const fs = require('node:fs');
function list(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}
module.exports = { list };

cli.cjs.text:
const { list } = require('./records.cjs');
const [file, command, ...args] = process.argv.slice(2);
try {
  if (!file || command !== 'list' || args.length) throw new Error('Usage: FILE list');
  process.stdout.write(JSON.stringify(list(file)) + '\n');
} catch (error) {
  process.stderr.write(error.message + '\n');
  process.exitCode = 2;
}

export.cjs.text:
const { list } = require('./records.cjs');
const rows = list(process.argv[2]);
process.stdout.write(rows.map(row => row.id).join(',') + '\n');

