const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
test('list and existing export preserve record order', () => {
  const listing = spawnSync(process.execPath, ['cli.cjs', 'data.json', 'list'], {cwd:root, encoding:'utf8'});
  assert.equal(listing.status, 0);
  assert.equal(listing.stderr, '');
  assert.deepEqual(JSON.parse(listing.stdout).map(row => row.id), ['t3','t1','t4','t2','t5','t6']);
  const exported = spawnSync(process.execPath, ['export.cjs', 'data.json'], {cwd:root, encoding:'utf8'});
  assert.equal(exported.status, 0);
  assert.equal(exported.stdout, 't3,t1,t4,t2,t5,t6\n');
});
